        let LayerTrainBuffers::Swin(train) = &mut executable.train_buffers[0] else {
            panic!("Swin train buffers")
        };
        train.updates.qkv_weight[0] = -0.2;
        train.updates.qkv_bias[0] = -0.1;
        train.updates.relative_position_bias[0] = -0.15;
